package app.manga.progress;
import java.security.Principal;import java.util.*;import app.manga.user.UserRepository;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/reading-progress")public class ProgressController{private final JdbcTemplate db;private final UserRepository users;public ProgressController(JdbcTemplate db,UserRepository users){this.db=db;this.users=users;}public record Progress(@NotBlank String provider,@Positive long externalMangaId,UUID readingSourceId,String chapterExternalId,@Size(max=100)String chapterLabel,@Min(0)Integer pageIndex,Double scrollPosition){}
 @GetMapping public Object list(Principal p){UUID u=uid(p);var rows=db.queryForList("select provider,external_manga_id,reading_source_id,chapter_external_id,chapter_label,page_index,scroll_position,last_read_at from reading_progress where user_id=? order by last_read_at desc nulls last",u);return Map.of("data",rows);}
 @PutMapping("/{provider}/{mangaId}")public Object put(Principal p,@PathVariable String provider,@PathVariable@Positive long mangaId,@Valid@RequestBody Progress b){if(!provider.equalsIgnoreCase("JIKAN")||!b.provider().equalsIgnoreCase(provider)||b.externalMangaId()!=mangaId)throw new IllegalArgumentException("Identitas progres tidak cocok.");if(b.scrollPosition()!=null&&b.scrollPosition()<0)throw new IllegalArgumentException("Posisi tidak valid.");if((b.chapterExternalId()!=null||b.chapterLabel()!=null||b.pageIndex()!=null)&&b.readingSourceId()==null)throw new IllegalArgumentException("Progres bab atau halaman memerlukan sumber bacaan tervalidasi.");if(b.readingSourceId()!=null){Integer count=db.queryForObject("select count(*) from reading_sources where id=? and provider=? and external_manga_id=? and verification_status='VERIFIED' and is_active=true",Integer.class,b.readingSourceId(),provider.toUpperCase(),mangaId);if(count==null||count==0)throw new IllegalArgumentException("Sumber bacaan belum terverifikasi.");}UUID u=uid(p);UUID id=UUID.randomUUID();db.update("insert into reading_progress(id,user_id,provider,external_manga_id,reading_source_id,chapter_external_id,chapter_label,page_index,scroll_position,last_read_at,updated_at) values(?,?,?,?,?,?,?,?,?,now(),now()) on conflict(user_id,provider,external_manga_id) do update set reading_source_id=excluded.reading_source_id,chapter_external_id=excluded.chapter_external_id,chapter_label=excluded.chapter_label,page_index=excluded.page_index,scroll_position=excluded.scroll_position,last_read_at=now(),updated_at=now()",id,u,provider.toUpperCase(),mangaId,b.readingSourceId(),b.chapterExternalId(),b.chapterLabel(),b.pageIndex(),b.scrollPosition());return Map.of("data",Map.of("provider",provider.toUpperCase(),"externalMangaId",mangaId,"lastReadAt",java.time.Instant.now()));}
 private UUID uid(Principal p){return users.findByEmail(p.getName()).orElseThrow().getId();}}
